package main

import (
	"html/template"
	"net/url"
)

func adminText(ja, en string) string {
	if currentLang() == "en" {
		return en
	}
	return ja
}

var adminTemplate = template.Must(template.New("admin").Funcs(template.FuncMap{
	"urlquery": url.QueryEscape,
	"t":        t,
	"tf":       tf,
	"lang":     currentLang,
	"x":        adminText,
}).Parse(`<!doctype html>
<html lang="{{lang}}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>{{t "app.title"}}</title>
<style>
:root{--bg:#fff;--text:#222;--sub:#6b6b6b;--line:#e9e9e7;--soft:#f7f7f5;--danger:#b42318;--ok:#2b7a3d;--warn:#8a6500}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:"Segoe UI","Yu Gothic UI",sans-serif}.wrap{max-width:1040px;margin:0 auto;padding:42px 28px 72px}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;padding-bottom:24px;border-bottom:1px solid var(--line)}h1{font-size:34px;letter-spacing:-.03em;margin:0 0 8px}.lead{color:var(--sub);font-size:15px;line-height:1.7;margin:0}.topActions{display:flex;align-items:flex-end;gap:10px;flex-wrap:wrap}.languageControl{display:flex;flex-direction:column;gap:4px;font-size:11px;color:var(--sub);font-weight:650}.languageControl select{font:inherit;font-size:13px;color:var(--text);background:#fff;border:1px solid #d7d7d7;border-radius:7px;padding:7px 28px 7px 9px}.badge{font-size:12px;font-weight:700;background:var(--soft);padding:7px 9px;border-radius:7px;color:#555}.btn,.fileLabel{display:inline-flex;align-items:center;justify-content:center;border:1px solid #d7d7d7;background:#fff;color:#222;border-radius:7px;padding:10px 14px;font-size:14px;font-weight:650;cursor:pointer;text-decoration:none}.btn:disabled{opacity:.55;cursor:default}.primary{background:#222;color:#fff;border-color:#222}.danger{color:var(--danger);border-color:#e5c4c0}.fileLabel input{display:none}.testHint{background:#fff7e6;border:1px solid #efcf8c;padding:11px 13px;border-radius:7px;font-size:14px;margin-top:16px}.wizardNav{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:24px 0 28px}.wizardNavItem{display:flex;align-items:center;gap:8px;min-width:0;padding:10px 12px;border:1px solid var(--line);border-radius:8px;color:var(--sub);font-size:12px;font-weight:700;background:#fff}.wizardNavItem .dot{width:24px;height:24px;display:grid;place-items:center;flex:0 0 24px;border-radius:50%;background:var(--soft);color:#666}.wizardNavItem.active{border-color:#222;color:#222}.wizardNavItem.active .dot{background:#222;color:#fff}.wizardNavItem.done .dot{background:#eaf6ed;color:#247238}.wizardStep{display:none}.wizardStep.active{display:block}.wizardCard{max-width:800px;margin:0 auto;border:1px solid var(--line);border-radius:12px;padding:28px;background:#fff}.wizardCard.wide{max-width:none}.wizardHead{display:flex;gap:14px;align-items:flex-start;margin-bottom:24px}.wizardNo{width:42px;height:42px;display:grid;place-items:center;flex:0 0 42px;border-radius:8px;background:#222;color:#fff;font-size:20px;font-weight:750}.wizardCard h2{font-size:25px;margin:3px 0 7px}.wizardCard p{margin:0;color:var(--sub);font-size:14px;line-height:1.7}.wizardBody{margin-top:20px}.qrGrid{display:grid;grid-template-columns:220px 1fr;gap:28px;align-items:start}.qr{width:220px;height:220px;border:1px solid #ddd;padding:7px;background:#fff}.label{font-size:12px;color:var(--sub);margin-bottom:4px}.value{font-size:17px;font-weight:650;overflow-wrap:anywhere}.mono{font-family:Consolas,"SFMono-Regular",monospace}.muted{color:var(--sub);font-size:13px;line-height:1.6}.url{font-size:12px;overflow-wrap:anywhere;color:#555;margin-top:6px}.details{margin-top:12px}.details summary{cursor:pointer;color:#555;font-size:13px}.notice{margin-top:14px;padding:12px 14px;background:var(--soft);border-radius:8px;color:#555;font-size:14px}.waiting{display:flex;align-items:center;gap:9px;margin-top:20px;padding:12px 14px;border-radius:8px;background:var(--soft);color:#555;font-size:14px}.waitingDot{width:9px;height:9px;border-radius:50%;background:#777;animation:pulse 1.2s infinite}.waiting.connected{background:#eef8f0;color:#246b35}.waiting.connected .waitingDot{background:var(--ok);animation:none}@keyframes pulse{0%,100%{opacity:.3}50%{opacity:1}}.wizardActions{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:26px}.rightActions{display:flex;gap:9px;margin-left:auto}.actions{display:flex;flex-wrap:wrap;gap:9px}.panels{display:grid;grid-template-columns:1fr 1fr;gap:26px;margin-top:24px}.panel{min-width:0}.panel h3{font-size:16px;margin:0 0 5px}.file{display:flex;gap:12px;padding:10px 0;border-bottom:1px solid var(--line)}.file span:first-child{flex:1;min-width:0;overflow-wrap:anywhere}.status{font-size:14px;color:var(--sub);margin-top:10px}.ok{color:var(--ok);font-weight:650}.doneIcon{width:58px;height:58px;display:grid;place-items:center;border-radius:50%;background:#eaf6ed;color:#247238;font-size:30px;font-weight:800;margin-bottom:18px}.modalBackdrop{display:none;position:fixed;inset:0;z-index:60;background:rgba(0,0,0,.45);padding:20px;align-items:center;justify-content:center}.modalBackdrop.open{display:flex}.modal{width:min(470px,100%);background:#fff;border-radius:12px;padding:24px;box-shadow:0 18px 55px rgba(0,0,0,.2)}.modal h2{font-size:21px;margin:0 0 10px}.modal p{color:var(--sub);font-size:14px;line-height:1.7;margin:0}.modalActions{display:flex;gap:9px;justify-content:flex-end;margin-top:22px}@media(max-width:760px){.wrap{padding:28px 18px 52px}.top{flex-direction:column}.wizardNav{grid-template-columns:1fr 1fr}.qrGrid{grid-template-columns:1fr}.qr{width:210px;height:210px}.panels{grid-template-columns:1fr}.wizardActions{align-items:stretch;flex-direction:column}.rightActions{width:100%;margin-left:0}.rightActions .btn,.wizardActions>.btn{width:100%}}@media(max-width:520px){.wizardNav{grid-template-columns:1fr}.wizardCard{padding:20px}.actions{display:grid;grid-template-columns:1fr}.actions .btn,.actions .fileLabel{width:100%}.modalActions{flex-direction:column-reverse}.modalActions .btn{width:100%}}
</style></head><body><main class="wrap">
<div class="top"><div><h1>{{t "app.title"}}</h1><p class="lead">{{tf "app.deviceLead" .DeviceName}}</p></div><div class="topActions">{{if .TestMode}}<div class="badge">{{t "app.testMode"}}</div>{{end}}<button id="globalStop" class="btn danger" onclick="stopApp()">{{t "finish.button"}}</button><label class="languageControl"><span>Language / 言語</span><select id="languageSelect" data-current="{{lang}}" aria-label="Language / 言語"><option value="ja" {{if eq (lang) "ja"}}selected{{end}}>日本語</option><option value="en" {{if eq (lang) "en"}}selected{{end}}>English</option></select></label></div></div>
{{if .TestMode}}<div class="testHint">{{t "app.testHint"}}</div>{{end}}
<div class="wizardNav" aria-label="Progress"><div class="wizardNavItem" data-nav="1"><span class="dot">1</span><span>{{x "Wi-Fi接続" "Wi-Fi"}}</span></div><div class="wizardNavItem" data-nav="2"><span class="dot">2</span><span>{{x "スマホで開く" "Open on phone"}}</span></div><div class="wizardNavItem" data-nav="3"><span class="dot">3</span><span>{{x "ファイル転送" "Transfer files"}}</span></div><div class="wizardNavItem" data-nav="4"><span class="dot">4</span><span>{{x "完了" "Done"}}</span></div></div>
<section class="wizardStep" data-step="1"><div class="wizardCard"><div class="wizardHead"><div class="wizardNo">1</div><div><h2>{{x "専用Wi-Fiに接続する" "Connect to the dedicated Wi-Fi"}}</h2><p>{{if .TestMode}}{{t "step1.testDescription"}}{{else}}{{x "スマートフォンをこのPCが作成した専用Wi-Fiに接続してください。" "Connect your smartphone to the dedicated Wi-Fi created by this PC."}}{{end}}</p></div></div><div class="wizardBody">{{if .WiFiQR}}<div class="qrGrid"><img class="qr" src="/qr.svg?text={{urlquery .WiFiQR}}" alt="Wi-Fi QR"><div><div class="label">{{t "wifi.name"}}</div><div class="value">{{.WiFiSSID}}</div><div style="height:16px"></div><div class="label">{{t "wifi.password"}}</div><div class="value mono">{{.WiFiPassword}}</div><div class="muted" style="margin-top:12px">{{t "wifi.noInternet"}}</div></div></div>{{else}}<div class="notice">{{t "wifi.notUsed"}}</div>{{end}}</div><div class="wizardActions"><span></span><div class="rightActions"><button class="btn primary" onclick="goToStep(2)">{{x "接続したので次へ" "Connected — Next"}} →</button></div></div></div></section>
<section class="wizardStep" data-step="2"><div class="wizardCard"><div class="wizardHead"><div class="wizardNo">2</div><div><h2>{{x "スマホで転送ページを開く" "Open the transfer page on your phone"}}</h2><p>{{if .TestMode}}{{t "step2.testDescription"}}{{else}}{{t "step2.description"}}{{end}}</p></div></div><div class="wizardBody">{{range $i,$u := .URLs}}{{if eq $i 0}}<div class="qrGrid"><img class="qr" src="/qr.svg?text={{urlquery $u.URL}}" alt="Transfer page QR"><div><div class="label">{{t "transfer.page"}}</div><div class="url">{{$u.URL}}</div><details class="details"><summary>{{t "transfer.connectionInfo"}}</summary><div class="muted" style="margin-top:8px">{{$u.Interface}} / {{$u.IP}}</div></details></div></div>{{end}}{{else}}<div class="notice">{{t "transfer.networkMissing"}}</div>{{end}}<div id="phoneWaiting" class="waiting"><span class="waitingDot"></span><span id="phoneWaitingText">{{x "スマートフォンからの接続を待っています…" "Waiting for your smartphone to connect…"}}</span></div></div><div class="wizardActions"><button class="btn" onclick="goToStep(1)">← {{x "戻る" "Back"}}</button><div class="rightActions"><button class="btn" onclick="markPhoneConnected()">{{x "スマホで開けたので次へ" "Opened on phone — Next"}} →</button></div></div></div></section>
<section class="wizardStep" data-step="3"><div class="wizardCard wide"><div class="wizardHead"><div class="wizardNo">3</div><div><h2>{{x "ファイルを転送する" "Transfer files"}}</h2><p>{{t "step3.description"}}</p></div></div><div class="actions"><label class="fileLabel primary">{{t "admin.pickFiles"}}<input id="sharePick" type="file" multiple></label><button class="btn" onclick="openFolder('send')">{{t "admin.openSend"}}</button><button class="btn" onclick="openFolder('receive')">{{t "admin.openReceive"}}</button></div><div id="shareStatus" class="status"></div><div class="panels"><div class="panel"><h3>{{t "admin.sendHeading"}}</h3><div class="muted">{{t "admin.sendDescription"}}</div><div id="sendList"></div><button class="btn danger" onclick="clearSide('send')" style="margin-top:12px">{{t "admin.clearSend"}}</button></div><div class="panel"><h3>{{t "admin.receiveHeading"}}</h3><div class="muted">{{t "admin.receiveDescription"}}</div><div id="recvList"></div><button class="btn danger" onclick="clearSide('receive')" style="margin-top:12px">{{t "admin.clearReceive"}}</button></div></div><div class="wizardActions"><button class="btn" onclick="goToStep(1)">← {{x "接続案内を見る" "View connection instructions"}}</button><div class="rightActions"><button class="btn primary" onclick="stopApp()">{{t "finish.button"}} →</button></div></div></div></section>
<section class="wizardStep" data-step="4"><div class="wizardCard"><div class="doneIcon">✓</div><h2>{{x "ファイル転送を終了しました" "File transfer ended"}}</h2><p id="doneBody">{{x "専用Wi-Fiも停止しました。スマートフォンは普段使っているWi-Fiやモバイル通信に戻してください。" "The dedicated Wi-Fi has also stopped. Reconnect your phone to its usual Wi-Fi or mobile data."}}</p><div class="wizardActions"><span></span><div class="rightActions"><button class="btn" onclick="closeWindow()">{{x "この画面を閉じる" "Close this window"}}</button></div></div></div></section>
</main>
<div id="idleModal" class="modalBackdrop" role="dialog" aria-modal="true"><div class="modal"><h2>{{x "まもなく自動終了します" "This session will end soon"}}</h2><p>{{x "しばらく操作がなかったため、この転送セッションはまもなく終了します。引き続き利用する場合は「利用を続ける」を押してください。" "There has been no activity for a while, so this transfer session will end soon. Select Continue using to keep the session active."}}</p><div class="modalActions"><button class="btn danger" onclick="stopApp()">{{x "今すぐ終了" "End now"}}</button><button class="btn primary" onclick="continueSession()">{{x "利用を続ける" "Continue using"}}</button></div></div></div>
<div id="absoluteModal" class="modalBackdrop" role="dialog" aria-modal="true"><div class="modal"><h2>{{x "まもなく利用可能時間の上限です" "Maximum session time is approaching"}}</h2><p>{{x "このセッションは安全上の利用時間上限に近づいています。この上限は延長できません。必要な転送を完了してください。" "This session is approaching its safety time limit. This limit cannot be extended. Complete any remaining transfers now."}}</p><div class="modalActions"><button class="btn danger" onclick="stopApp()">{{x "今すぐ終了" "End now"}}</button><button class="btn" onclick="dismissAbsoluteWarning()">{{x "確認しました" "Got it"}}</button></div></div></div>
<script>
const admin='/admin/{{.AdminToken}}';const sessionKey='{{.AdminToken}}';const currentLocale='{{lang}}';let allowClose=false;let sessionEnded=false;let currentStep=1;let lastIdle=null;let step2EnteredAtIdle=null;let phoneTransitionPending=false;let idleModalVisible=false;let absoluteWarningDismissed=false;
const msg={preparing:{{t "admin.preparing"}},shareReady:{{t "admin.shareReady"}},confirmClearSend:{{t "admin.confirmClearSend"}},confirmClearReceive:{{t "admin.confirmClearReceive"}},emptySend:{{t "admin.emptySend"}},emptyReceive:{{t "admin.emptyReceive"}},finishConfirm:{{t "finish.confirm"}},timeoutBody:{{t "finish.timeoutBody"}},phoneConnected:{{x "スマートフォンが接続されました" "Smartphone connected"}},doneBody:{{x "専用Wi-Fiも停止しました。スマートフォンは普段使っているWi-Fiやモバイル通信に戻してください。" "The dedicated Wi-Fi has also stopped. Reconnect your phone to its usual Wi-Fi or mobile data."}},ended:{{x "終了済み" "Ended"}}};
if(sessionStorage.getItem('oftWizardSession')!==sessionKey){sessionStorage.setItem('oftWizardSession',sessionKey);sessionStorage.setItem('oftWizardStep','1')}currentStep=Number(sessionStorage.getItem('oftWizardStep')||1);if(currentStep<1||currentStep>3)currentStep=1;
window.addEventListener('beforeunload',e=>{if(!allowClose){e.preventDefault();e.returnValue=''}});
document.getElementById('languageSelect').addEventListener('change',async e=>{const previous=e.target.dataset.current;const body=new URLSearchParams({locale:e.target.value});try{const r=await fetch(admin+'/locale',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!r.ok)throw 0;allowClose=true;location.reload()}catch(_){e.target.value=previous;alert('Language setting could not be saved. / 言語設定を保存できませんでした。')}});
function goToStep(step){if(sessionEnded)step=4;currentStep=step;if(step<4)sessionStorage.setItem('oftWizardStep',String(step));if(step===2)step2EnteredAtIdle=lastIdle;document.querySelectorAll('.wizardStep').forEach(el=>el.classList.toggle('active',Number(el.dataset.step)===step));document.querySelectorAll('.wizardNavItem').forEach(el=>{const n=Number(el.dataset.nav);el.classList.toggle('active',n===step);el.classList.toggle('done',n<step)});const stop=document.getElementById('globalStop');if(step===4){stop.disabled=true;stop.textContent=msg.ended}else{stop.disabled=false}window.scrollTo({top:0,behavior:'smooth'})}
function markPhoneConnected(){if(phoneTransitionPending||sessionEnded)return;phoneTransitionPending=true;const w=document.getElementById('phoneWaiting');w.classList.add('connected');document.getElementById('phoneWaitingText').textContent=msg.phoneConnected;setTimeout(()=>goToStep(3),650)}
function fmt(n){if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';if(n<1073741824)return(n/1048576).toFixed(1)+' MB';return(n/1073741824).toFixed(2)+' GB'}
document.getElementById('sharePick').addEventListener('change',async e=>{const st=document.getElementById('shareStatus');for(const f of e.target.files){st.textContent=msg.preparing+f.name;await rawUpload(f)}st.textContent=msg.shareReady;st.className='status ok';e.target.value='';loadStatus()});
function rawUpload(f){return new Promise(res=>{const x=new XMLHttpRequest();x.open('POST',admin+'/upload?name='+encodeURIComponent(f.name));x.onload=()=>res();x.onerror=()=>res();x.send(f)})}
async function openFolder(which){await fetch(admin+'/open?which='+which,{method:'POST'})}
async function clearSide(which){if(!confirm(which==='send'?msg.confirmClearSend:msg.confirmClearReceive))return;await fetch(admin+'/clear-'+which,{method:'POST'});loadStatus()}
function render(id,fs,empty){const el=document.getElementById(id);if(!fs.length){el.innerHTML='<div class="muted" style="padding:10px 0"></div>';el.firstChild.textContent=empty;return}el.innerHTML='';for(const f of fs){const d=document.createElement('div');d.className='file';const n=document.createElement('span');n.textContent=f.name;const z=document.createElement('span');z.className='muted';z.textContent=fmt(f.size);d.append(n,z);el.appendChild(d)}}
function showIdleWarning(){if(sessionEnded||idleModalVisible)return;idleModalVisible=true;document.getElementById('idleModal').classList.add('open')}
async function continueSession(){const body=new URLSearchParams({locale:currentLocale});try{const r=await fetch(admin+'/locale',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!r.ok)throw 0;document.getElementById('idleModal').classList.remove('open');idleModalVisible=false;await loadStatus()}catch(_){} }
function showAbsoluteWarning(){if(sessionEnded||absoluteWarningDismissed)return;document.getElementById('absoluteModal').classList.add('open')}
function dismissAbsoluteWarning(){absoluteWarningDismissed=true;document.getElementById('absoluteModal').classList.remove('open')}
function finishLocally(body){sessionEnded=true;allowClose=true;document.getElementById('idleModal').classList.remove('open');document.getElementById('absoluteModal').classList.remove('open');document.getElementById('doneBody').textContent=body;sessionStorage.setItem('oftWizardStep','4');goToStep(4)}
async function stopApp(){if(sessionEnded)return;if(!confirm(msg.finishConfirm))return;try{await fetch(admin+'/stop',{method:'POST'})}catch(_){}finishLocally(msg.doneBody)}
function closeWindow(){allowClose=true;window.close()}
async function loadStatus(){if(sessionEnded)return;try{const r=await fetch(admin+'/api/status',{cache:'no-store'});if(!r.ok)throw 0;const s=await r.json();render('sendList',s.send,msg.emptySend);render('recvList',s.receive,msg.emptyReceive);const idle=Number(s.idleRemainingSec||0),absolute=Number(s.absoluteRemainingSec||0);if(currentStep===2&&!phoneTransitionPending){if(s.phoneConnected===true||(lastIdle!==null&&idle>lastIdle)||(step2EnteredAtIdle!==null&&idle>step2EnteredAtIdle)){markPhoneConnected()}}lastIdle=idle;if(idle<=0||absolute<=0){finishLocally(msg.timeoutBody);return}if(absolute<=300){showAbsoluteWarning()}else if(idle<=300){showIdleWarning()}}catch(_){} }
goToStep(currentStep);loadStatus();setInterval(loadStatus,2000);
</script></body></html>`))
